package com.lebzlon.measurementtracker.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.*;
@Entity @Table(name="meter_readings", uniqueConstraints=@UniqueConstraint(columnNames={"meter_id","readingTimestamp"}))
public class MeterReading { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(nullable=false) private Meter meter; @Column(name="readingTimestamp",nullable=false) private Instant timestamp; @Column(nullable=false,precision=12,scale=3) private BigDecimal value; @Enumerated(EnumType.STRING) @Column(nullable=false) private ReadingSource source; private String imagePath; @Column(columnDefinition="TEXT") private String ocrRawText; @Column(nullable=false) private Instant createdAt=Instant.now();
public Long getId(){return id;} public Meter getMeter(){return meter;} public void setMeter(Meter m){this.meter=m;} public Instant getTimestamp(){return timestamp;} public void setTimestamp(Instant t){this.timestamp=t;} public BigDecimal getValue(){return value;} public void setValue(BigDecimal v){this.value=v;} public ReadingSource getSource(){return source;} public void setSource(ReadingSource s){this.source=s;} public String getImagePath(){return imagePath;} public void setImagePath(String i){this.imagePath=i;} public String getOcrRawText(){return ocrRawText;} public void setOcrRawText(String o){this.ocrRawText=o;} }
